from pathlib import Path
import json
R=Path('/home/ding/vivado_project/Lab6_growth_trials');rows=json.loads((R/'results/comparison.json').read_text());base=rows[0]
labels={'fc2_interleaved_split11':'当前基线','fc1_128x6_dual':'FC1 128×6 并行＋双输入 FC2','zero_gate':'FC2 零值门控','tail8':'FC2→FC3 每拍 8 路','fc1_csa_tree':'FC1 进位保存压缩＋加法树'}
s=['# Lab6 四方向优化试验结果','', '四方向均已完成。此次只有 FC1 128×6 并行＋双输入 FC2 取得正收益：延迟降低 6.86%，连续任务吞吐率提高 20.74%。建议将其保留为性能候选，原低资源基线继续保留；另三项不合入。','', '比较基准为 `fc2_interleaved_split11`，174 拍、4.09 ns，端到端延迟 711.66 ns。所有试验保持原 INT8 模型、权重、偏置和量化规则。','', '| 方案 | 拍数 | 周期/ns | 延迟/ns | 延迟降低 | 启动间隔/ns | LUT | FF | BRAM | DSP | 时序/布线 |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---|']
for x in rows:
 ok=x.get('timing_pass') and x.get('route_errors')==0
 vals=[labels[x['name']],x.get('cycles','—'),x.get('period','—'),x.get('latency_ns','—'),str(x.get('improvement_percent','—'))+'%',x.get('interval_ns','—'),x.get('lut','—'),x.get('ff','—'),x.get('bram','—'),x.get('dsp','—'),'通过' if ok else x.get('impl')]
 s.append('| '+' | '.join(map(str,vals))+' |')
s+=['','## 每项实际做了什么','', '1. **FC1 扩展并行度。** 由 256 个输入×2 个输出改为 128 个输入×6 个输出，每拍标量乘法由 512 增至 768。三个双输出计算核各处理 4 组输入，22 个输出批次需要 88 个计算发射拍，最后一批只取两个有效输出。用 6 项小缓冲每拍发送两个结果，FC2 每拍消费两个输入并累加两项乘积。FC1 使用 184 个 DSP，其余配对乘法用 LUT；FC2 用 32 个 DSP，FC3 用 4 个，总计 220。拍数减少，但 LUT、寄存器和权重存储显著增加，物理时序必须实测。','', '2. **零值门控。** FC2 输入为零时不更新乘法结果与累加状态，但保留首次清零、奇偶累加初始化和结束标记。数据、地址、valid 管线保持对齐。此次实现不压缩输入时间槽，所以不会减少总拍数；也没有测量功耗，不能据此宣称功耗降低。真正跳过时间槽还需要 FC1 更快地产生非零输入或缓冲批量输入，不能直接把约 74% 的零值率换成 74% 的整网加速。','', '3. **缩短尾部。** FC2 每拍输出由 4 项增至 8 项；FC3 使用 8 个 DSP，每拍消费 8 项。FC1 将 4 个 DSP 通道改为 LUT，并重新编码对应权重，维持整网 220 DSP。FC2 输出阶段减少 4 拍，而 FC3 加法归约多一级，所以实测净减少 3 拍。启动间隔仍受 FC1 限制。','', '4. **修改 FC1 加法树。** 将第一层二输入加法改为三输入进位保存压缩器，先生成和与进位，再做流水二叉树归约。压缩器与后续流水共 9 级，比原树多 1 级，valid、地址和偏置同步延长。是否值得取决于时钟改善能否抵消增加的拍数，不能只按逻辑结构判断。','', '## 校验范围','', '每版均完成保存后的 DCP 检查与最终周期下的 RTL 复核。每版先进行 48 组连续任务的 RTL 仿真，以整数参考模型逐个比较所有层输出，含 42 个原始样本及重复任务，共 7776 个输出值/地址检查。分类正确数保持 37/42，数值错误为 0。布局布线结果需同时满足 setup、hold、脉宽和零布线错误。最终周期采用已布线路径推导并重新约束得到，未进行板上测试；最终复核仍是 RTL 仿真，不是含 SDF 的门级仿真。','', '## 复现与文件','', f'- 工程根目录：[{R}]({R})',f'- 全部结果：[comparison.json]({R}/results/comparison.json)、[comparison.csv]({R}/results/comparison.csv)',f'- 试验定义：[prepare.py]({R}/tools/prepare.py)',f'- 运行器：[run_trials.py]({R}/tools/run_trials.py)','', '各工程的 `results/` 保留功能日志、综合/实现资源报告、最终时序报告、布线状态与 routed DCP；`tools/run_final_verify.tcl` 用最终时钟重新检查保存的 DCP 并运行数值仿真。每版仅做一次完整实现，没有为获得好看的结果反复随机调参。原基线工程未覆盖。']
p=Path('/home/ding/桌面/Lab/Lab6四方向优化试验结果.md');p.write_text('\n'.join(s)+'\n');print(p)
